import{_ as n,a0 as p,w as r,s as o,ao as d,I as l,x as t,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何逐步安装 Kubernetes（k8s）指标服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何逐步安装 Kubernetes（k8s）指标服务器 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何逐步安装 Kubernetes（k8s）指标服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何逐步安装 Kubernetes（k8s）指标服务器 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230327.0 ⭐️ How to Install Kubernetes (K8s) Metrics Server Step by Step","title":"如何逐步安装 Kubernetes（k8s）指标服务器","tag":"202304","desc":""},"relativePath":"202304/20230327.0 ⭐️ How to Install Kubernetes (K8s) Metrics Server Step by Step.md","filePath":"[post].md"}'),h={name:"202304/20230327.0 ⭐️ How to Install Kubernetes (K8s) Metrics Server Step by Step.md"};function u(c,e,b,g,k,m){const s=p("Link");return r(),o("div",null,[e[15]||(e[15]=d(`<h1 id="如何逐步安装-kubernetes-k8s-指标服务器" tabindex="-1">如何逐步安装 Kubernetes（k8s）指标服务器 <a class="header-anchor" href="#如何逐步安装-kubernetes-k8s-指标服务器" aria-label="Permalink to “如何逐步安装 Kubernetes（k8s）指标服务器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/12/100919k6p6yyweu6nv6nkh.jpg" alt=""></p><blockquote><p>在这篇文章中，我们将逐步介绍如何安装 Kubernetes 指标服务器。</p></blockquote><p>Kubernetes（k8s）指标服务器是一个组件，用于收集和聚合来自 Kubernetes 集群中各种来源（包括节点和 <ruby>容器荚<rt>Pod</rt></ruby>）的指标数据。此数据可用于监控和优化资源利用率、识别潜在问题并提高 Kubernetes 集群的整体性能。</p><p>指标服务器收集资源利用率数据，例如集群中节点和容器荚的 CPU 和内存使用情况。它提供了一个 API 端点，可用于查询此数据并检索集群中特定资源的指标。</p><h5 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to “先决条件”">​</a></h5><ul><li>启动并运行 Kubernetes 集群（v1.21 或更高版本）。</li><li><code>kubectl</code> 命令行工具已安装，并配置为与你的 Kubernetes 集群交互。</li><li>创建和修改 Kubernetes 对象的能力。</li></ul><p>事不宜迟，让我们深入了解安装步骤。</p><h3 id="步骤-1-下载指标服务器清单" tabindex="-1">步骤 1 下载指标服务器清单 <a class="header-anchor" href="#步骤-1-下载指标服务器清单" aria-label="Permalink to “步骤 1 下载指标服务器清单”">​</a></h3><p>第一步是从 Kubernetes GitHub 仓库下载最新的指标服务器清单文件。使用下面的 <code>curl</code> 命令下载 yaml 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># curl -LO https://github.com/kubernetes-sigs/metrics-server/releases/latest/download/components.yaml</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Download-Metrics-Server-Yaml-file-Curl-Command-1024x127.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>如果你计划在高可用性模式下安装指标服务器，请下载以下清单文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># curl https://github.com/kubernetes-sigs/metrics-server/releases/latest/download/high-availability-1.21+.yaml</span></span></code></pre></div><h3 id="步骤-2-修改指标服务器-yaml-文件" tabindex="-1">步骤 2 修改指标服务器 Yaml 文件 <a class="header-anchor" href="#步骤-2-修改指标服务器-yaml-文件" aria-label="Permalink to “步骤 2 修改指标服务器 Yaml 文件”">​</a></h3><p>接下来，你需要修改指标服务器的 yaml 文件以设置一些配置选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi components.yaml</span></span></code></pre></div><p>找到 <code>container</code> 下的 <code>args</code> 部分，添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- --kubelet-insecure-tls</span></span></code></pre></div><p>在 <code>spec</code> 下，添加以下参数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hostNetwork: true</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Edit-Metrics-Server-Yaml-file.png" alt=""></p><p>保存并关闭文件。</p><h3 id="步骤-3-部署指标服务器" tabindex="-1">步骤 3 部署指标服务器 <a class="header-anchor" href="#步骤-3-部署指标服务器" aria-label="Permalink to “步骤 3 部署指标服务器”">​</a></h3><p>现在，我们准备好部署指标服务器，运行以下 <code>kubectl</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># kubectl apply -f components.yaml</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Deploy-Metrics-Server-Kubectl-Command.png" alt=""></p><h3 id="步骤-4-验证指标服务器部署" tabindex="-1">步骤 4 验证指标服务器部署 <a class="header-anchor" href="#步骤-4-验证指标服务器部署" aria-label="Permalink to “步骤 4 验证指标服务器部署”">​</a></h3><p>部署指标服务器后，通过检查在 <code>kube-system</code> 命名空间中运行的容器荚状态来验证它的状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># kubectl get pods -n kube-system</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Metrics-Server-Pods-Status-Kube-System.png" alt=""></p><p>上面的输出确认指标服务器容器荚已启动并正在运行。</p><h3 id="步骤-5-测试指标服务器安装" tabindex="-1">步骤 5 测试指标服务器安装 <a class="header-anchor" href="#步骤-5-测试指标服务器安装" aria-label="Permalink to “步骤 5 测试指标服务器安装”">​</a></h3><p>最后，你可以通过运行以下 <code>kubectl</code> 命令来测试指标服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># kubectl top nodes</span></span></code></pre></div><p>此命令应显示集群中每个节点的资源利用率，包括 CPU 和内存使用率。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Kubectl-top-node-command-Output.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>要查看当前命名空间或特定命名空间的容器荚资源利用率，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># kubectl top pod</span></span>
<span class="line"><span># kubectl top pod -n kube-system</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Kubectl-top-pod-command-output.png" alt=""></p><p>这就是这篇文章的全部内容，我希望你能从中找到有用的信息。请在下面的评论部分发表你的反馈和疑问。</p><p><em>（题图：MJ: Kubernetes container paper art light blue background ultra-detailed topview）</em></p><hr>`,43)),l("p",null,[e[1]||(e[1]=t("via: ",-1)),i(s,{href:"https://www.linuxtechi.com/how-to-install-kubernetes-metrics-server/"},{default:a(()=>[...e[0]||(e[0]=[t("https://www.linuxtechi.com/how-to-install-kubernetes-metrics-server/",-1)])]),_:1})]),l("p",null,[e[6]||(e[6]=t("作者：",-1)),i(s,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...e[2]||(e[2]=[t("Pradeep Kumar",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),i(s,{href:"https://github.com/lkxed/"},{default:a(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:a(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[12]||(e[12]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const x=n(h,[["render",u]]);export{w as __pageData,x as default};
